export function headings(markdown: string) {
  return markdown
    .split("\n")
    .filter((LINE) => /^##\s/.test(LINE))
    .map((LINE) => {
      const text = LINE.replace(/^##\s+/, "").replace(/[*`]/g, "")
      return { text, id: slugify(LINE.replace(/^##\s+/, "")) }
    })
}
